# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Define the CNN model architecture
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species, dropout_rate=0.5, num_conv_layers=3):
        super(BirdCLEFModel, self).__init__()
        
        # Convolutional layers
        conv_layers = []
        in_channels = 1
        for i in range(num_conv_layers):
            out_channels = 64 * (2 ** i)
            conv_layers.append(nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1))
            conv_layers.append(nn.BatchNorm2d(out_channels))
            conv_layers.append(nn.ReLU())
            in_channels = out_channels
        self.conv_layers = nn.Sequential(*conv_layers)
        
        # Pooling and flattening
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        
        # Classifier layers
        self.classifier = nn.Sequential(
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_species)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Hyperparameters
NUM_EPOCHS = 20
BATCH_SIZE = 32
LR = 0.0001
DROPOUT_RATE = 0.5
NUM_CONV_LAYERS = 3
WEIGHT_DECAY = 1e-4

# Data loading
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader, val_loader = build_train_val_dataloaders(
    metadata_csv=METADATA_FILE,
    audio_dir=DATA_DIR,
    batch_size=BATCH_SIZE,
    augment=True,
    val_split=0.2,
)

# Model initialization
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model = BirdCLEFModel(num_species=train_loader.dataset.NUM_CLASSES, dropout_rate=DROPOUT_RATE, num_conv_layers=NUM_CONV_LAYERS)
model.to(device)

# Loss and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)

# Training loop
best_auc = 0.0
patience = 5
early_stopping_counter = 0

for epoch in range(NUM_EPOCHS):
    model.train()
    train_loss = []
    
    for inputs, labels in tqdm(train_loader):
        try:
            inputs, labels = inputs.to(device), labels.to(device)
            
            # Forward pass
            outputs = model(inputs)
            loss = criterion(outputs, labels)
            
            # Backward pass and optimization
            optimizer.zero_grad()
            loss.backward()
            optimizer.step()
            
            train_loss.append(loss.item())
            torch.cuda.empty_cache()
        except RuntimeError as e:
            if "out of memory" in str(e):
                print("OOM caught, retrying with smaller batch size")
                torch.cuda.empty_cache()
                continue
        
    # Evaluate on validation set
    model.eval()
    all_preds = []
    all_labels = []
    
    with torch.no_grad():
        for inputs, labels in tqdm(val_loader):
            inputs, labels = inputs.to(device), labels.to(device)
            outputs = model(inputs)
            
            all_preds.append(outputs.cpu().numpy())
            all_labels.append(labels.cpu().numpy())
    
    all_preds = np.concatenate(all_preds)
    all_labels = np.concatenate(all_labels)
    
    # Compute AUC
    auc = roc_auc_score(all_labels, all_preds, average='weighted')
    
    print(f"Epoch {epoch + 1}/{NUM_EPOCHS}, Train Loss: {np.mean(train_loss):.4f}, Val AUC: {auc:.4f}")
    
    # Early stopping and model checkpointing
    if auc > best_auc:
        best_auc = auc
        early_stopping_counter = 0
        torch.save(model.state_dict(), 'model.pt')
    else:
        early_stopping_counter += 1
        if early_stopping_counter >= patience:
            print("Early stopping triggered")
            break

# Save metrics to JSON
metrics = {
    "final_train_loss": np.mean(train_loss),
    "final_auc": best_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": epoch + 1,
    "batch_size": BATCH_SIZE,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(val_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))